INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63393183', 63393183, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA PELABUHAN PERIKANAN', 'Pengawasan Peninggian Area Bongkar Muat UPI', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Utara (Kota)', 99500000, 'July 2026', 'APBD', 1, 1, '1 paket', 'Pengawasan pekerjaan peninggian area bongkar muat Unit Pengolahan Ikan (UPI) di lingkungan Unit Pengelola Pelabuhan Perikanan (UPPP), khususnya pekerjaan peninggian jalan/area kerja, yang dilaksanakan untuk memastikan pelaksanaan konstruksi sesuai dengan dokumen perencanaan teknis, spesifikasi, mutu, waktu, dan biaya yang telah ditetapkan. Kegiatan pengawasan meliputi pemeriksaan kesiapan pelaksanaan pekerjaan, pengawasan harian terhadap metode kerja, material, dan peralatan yang digunakan, serta pengendalian mutu pekerjaan perkerasan dan drainase. Pengawas melakukan pengecekan elevasi hasil peninggian, ketebalan lapisan, kemiringan permukaan, dan fungsi saluran drainase agar sesuai dengan desain dan tidak menimbulkan genangan. Selain itu, pengawasan mencakup pemantauan keselamatan dan kesehatan kerja (K3), pengaturan tahapan pekerjaan agar tidak mengganggu aktivitas bongkar muat UPI, serta pencatatan progres fisik pekerjaan. Hasil pengawasan dituangkan dalam laporan harian, mingguan, dan bulanan, termasuk rekomendasi teknis dan evaluasi hasil pekerjaan sebagai dasar penerimaan pekerjaan peninggian area bongkar muat UPI.', 'Pengawasan pekerjaan peninggian area bongkar muat Unit Pengolahan Ikan (UPI) di lingkungan Unit Pengelola Pelabuhan Perikanan (UPPP), khususnya pekerjaan peninggian jalan/area kerja, yang dilaksanakan untuk menjamin kesesuaian pelaksanaan konstruksi dengan dokumen perencanaan teknis, spesifikasi, gambar kerja, jadwal, dan anggaran yang telah ditetapkan. Pengawasan dilakukan oleh tenaga ahli yang berkompeten dan berpengalaman di bidang pekerjaan jalan dan bangunan pelabuhan. Ruang lingkup spesifikasi pengawasan meliputi: Pengawasan Teknis Pemeriksaan kesesuaian metode kerja dengan rencana Pengawasan pekerjaan tanah, lapis pondasi, dan lapis perkerasan Pengukuran dan verifikasi elevasi, ketebalan, kemiringan, dan dimensi pekerjaan Pengawasan pekerjaan drainase dan pengendalian air Pengendalian Mutu Pemeriksaan mutu material dan hasil pekerjaan Pengujian mutu sesuai standar teknis yang berlaku Evaluasi hasil pekerjaan dan rekomendasi perbaikan bila diperlukan Pengendalian Waktu dan Biaya Pemantauan progres fisik dan kesesuaian dengan jadwal pelaksanaan Verifikasi volume pekerjaan dan administrasi pembayaran Keselamatan dan Lingkungan Pengawasan penerapan Keselamatan dan Kesehatan Kerja (K3) Pengawasan pengelolaan lingkungan kerja agar aktivitas bongkar muat tetap berjalan aman Pelaporan Penyusunan laporan pengawasan harian, mingguan, dan bulanan Penyusunan laporan akhir pengawasan sebagai dasar serah terima pekerjaan Hasil pekerjaan berupa laporan pengawasan lengkap dan rekomendasi teknis untuk menjamin pekerjaan peninggian area bongkar muat UPI terlaksana sesuai rencana dan siap digunakan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 910424);
