INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63372902', 63372902, 'analyze_legacy', 'Kejaksaan Republik Indonesia', 'central', 'KEJAKSAAN NEGERI ROKAN HILIR', 'Belanja Tenaga PPNPN (Outsourcing)', 'Jasa Lainnya', 'E-Purchasing', 'Riau, Rokan Hilir (Kab.)', 1085678000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Belanja Tenaga PPNPN (Outsourcing) dimaksudkan untuk mendukung kelancaran operasional dan pelayanan perkantoran melalui penyediaan tenaga kerja alih daya dengan formasi 1 orang pengawas, 6 orang satuan pengamanan (satpam), 6 orang petugas kebersihan (cleaning service), 1 orang pengemudi (supir), 1 orang petugas PTSP, dan 2 orang pramubakti. Pengawas bertugas mengoordinasikan, mengendalikan, dan mengevaluasi kinerja seluruh tenaga outsourcing; satpam bertanggung jawab atas keamanan dan ketertiban lingkungan kerja; cleaning service melaksanakan kebersihan dan pemeliharaan sarana prasarana; supir mendukung operasional kendaraan dinas; petugas PTSP memberikan layanan administrasi dan informasi kepada masyarakat; sedangkan pramubakti membantu kegiatan administrasi dan operasional harian kantor.', 'Spesifikasi pekerjaan mencakup pemenuhan tenaga kerja yang memiliki kompetensi sesuai bidang tugas, disiplin, serta beretika pelayanan, dengan pengaturan jam kerja sesuai kebutuhan operasional. Belanja ini meliputi pembayaran upah dan tunjangan, biaya pengawasan, penyediaan seragam kerja, pemenuhan kewajiban perpajakan, serta kepesertaan BPJS Ketenagakerjaan dan BPJS Kesehatan, termasuk komponen biaya lain yang melekat guna menjamin perlindungan, kesejahteraan tenaga kerja, dan mutu layanan yang berkesinambungan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 912253);
