INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63350910', 63350910, 'analyze_legacy', 'Kab. Blitar', 'kabkota', 'RSUD Ngudi Waluyo Wlingi', '- BELANJA JASA KONSULTANSI LAINNYA-JASA KONSULTANSI ESTIMASI NILAI LAHAN DAN BANGUNAN - JASA PENILAIAN ASET', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Timur, Blitar (Kab.)', 50000000, 'February 2026', 'BLUD', 1, 1, '1 PAKET', 'BELANJA JASA KONSULTANSI LAINNYA-JASA KONSULTANSI ESTIMASI NILAI LAHAN DAN BANGUNAN - JASA PENILAIAN ASET', 'A. Tugas dan Fungsi KJPP: 1. Penilaian Properti: a. Menilai harga properti dalam proses KPR, termasuk menentukan plafon pinjaman yang bisa diajukan. b. Menilai properti untuk transaksi jual beli, memastikan harga sesuai dengan nilai pasar. c. Menilai properti untuk keperluan lelang, likuidasi, atau penyelesaian sengketa. 2. Penilaian Bisnis dan Aset: a. Menilai nilai bisnis, misalnya dalam hal penjualan saham atau aset perusahaan. b. Menilai aset-aset terkait bisnis, seperti persediaan kayu pada Perhutani. 3. Jasa Lainnya: a. Studi kelayakan bisnis. b. Pengelolaan aset properti. c. Konsultasi properti. d. Pengawasan pembiayaan proyek. e. Penilaian objek kegiatan pengadaan tanah. f. Penataan ruang lainnya. B. Pentingnya KJPP: 1. Akurasi Penilaian: a. KJPP memberikan penilaian yang akurat dan objektif berdasarkan standar penilaian yang berlaku. b. Dasar Pengambilan Keputusan: c. Hasil penilaian KJPP menjadi dasar penting dalam berbagai transaksi dan pengambilan keputusan keuangan. 2. Mencegah Kerugian: Penilaian yang akurat membantu mencegah kerugian akibat kesalahan dalam menentukan nilai aset. 3. Mendukung Proses Hukum: a. Penilaian KJPP dapat digunakan dalam penyelesaian sengketa properti atau bisnis. b. Secara keseluruhan, KJPP berperan penting dalam memastikan penilaian aset yang adil dan akurat, yang mendukung berbagai transaksi bisnis, keuangan, dan hukum', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 912640);
