INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63395133', 63395133, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA PELABUHAN PERIKANAN', 'Pengendalian Mutu Komoditi dan Produk Hasil Perikanan', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Utara (Kota)', 214337872, 'February 2026', 'APBD', 1, 1, '1 paket', 'Pengendalian mutu komoditi dan produk hasil perikanan di lingkungan Unit Pengelola Pelabuhan Perikanan (UPPP) yang dilaksanakan untuk menjamin mutu, keamanan, dan kelayakan konsumsi produk perikanan sejak penanganan awal hingga distribusi. Kegiatan ini bertujuan mendukung pemenuhan standar mutu, sanitasi, dan higiene sesuai ketentuan peraturan perundang-undangan yang berlaku. Ruang lingkup pekerjaan meliputi pemeriksaan fisik dan organoleptik komoditi hasil perikanan (kesegaran, bau, warna, tekstur), pengawasan penerapan sanitasi dan higiene pada area bongkar muat, Tempat Pelelangan Ikan (TPI), gudang, dan sarana pendukung lainnya. Selain itu dilakukan pemantauan rantai dingin (cold chain), penggunaan es, serta kebersihan peralatan dan wadah penanganan ikan. Kegiatan pengendalian mutu juga mencakup pengambilan sampel bila diperlukan, pencatatan dan pendokumentasian hasil pemeriksaan, serta penyampaian rekomendasi teknis terhadap komoditi dan produk yang tidak memenuhi persyaratan mutu. Apabila ditemukan ketidaksesuaian, dilakukan koordinasi tindak lanjut sesuai prosedur yang berlaku. Seluruh kegiatan dilaksanakan secara berkelanjutan dan terkoordinasi, dengan hasil pekerjaan berupa laporan pengendalian mutu, data pemantauan kondisi komoditi, serta rekomendasi perbaikan guna meningkatkan kualitas dan daya saing produk hasil perikanan di lingkungan UPPP.', 'Pengendalian mutu komoditi dan produk hasil perikanan di lingkungan Unit Pengelola Pelabuhan Perikanan (UPPP) dilaksanakan untuk memastikan produk perikanan memenuhi persyaratan mutu, keamanan pangan, sanitasi, dan higiene sesuai standar dan ketentuan peraturan perundang-undangan yang berlaku. Ruang lingkup spesifikasi meliputi: Pemeriksaan Mutu Produk Pemeriksaan fisik dan organoleptik (kesegaran, warna, bau, tekstur) Pemeriksaan kondisi kemasan dan wadah penanganan produk Pemantauan suhu dan penerapan rantai dingin (cold chain) Pengawasan Sanitasi dan Higiene Pengawasan kebersihan area bongkar muat, TPI, gudang, dan sarana pendukung Pengawasan kebersihan peralatan, wadah, dan alat angkut Pemantauan higiene pelaku usaha dan petugas penanganan produk Pengambilan Sampel dan Pengujian (bila diperlukan) Pengambilan sampel komoditi dan produk hasil perikanan Koordinasi pengujian laboratorium sesuai ketentuan yang berlaku Pencatatan dan Pelaporan Pencatatan hasil pemeriksaan dan pemantauan mutu Penyusunan laporan kegiatan pengendalian mutu secara berkala Dokumentasi temuan dan rekomendasi perbaikan Tindak Lanjut dan Rekomendasi Pemberian rekomendasi teknis terhadap produk yang tidak memenuhi persyaratan Koordinasi penanganan produk bermasalah sesuai prosedur Edukasi singkat kepada pelaku usaha terkait peningkatan mutu penanganan produk Standar dan Ketentuan Mengacu pada standar mutu dan keamanan pangan hasil perikanan yang berlaku Memperhatikan aspek keselamatan kerja dan perlindungan lingkungan Hasil pekerjaan berupa laporan pengendalian mutu komoditi dan produk hasil perikanan yang dapat digunakan sebagai dasar evaluasi dan peningkatan kualitas pelayanan serta daya saing produk perikanan di lingkungan UPPP.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 914386);
