INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63351964', 63351964, 'analyze_legacy', 'Kab. Karanganyar', 'kabkota', 'Dinas Pekerjaan Umum dan Perumahan Rakyat', 'Beban Jasa Konsultansi Berorientasi Layanan-Jasa Khusus', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Tengah, Karanganyar (Kab.)', 100000000, 'February 2026', 'APBD', 1, 1, '1 Paket', 'Beban Jasa Konsultansi Berorientasi Layanan-Jasa Khusus; Uraian pekerjaan pengintegrasian Rencana Detail Tata Ruang (RDTR) ke Sistem Online Single Submission (OSS) di wilayah tawangmangu mencakup penyusunan kelengkapan dokumen RDTR digital standar agar perizinan berusaha (KKPR) bisa cepat, transparan, dan sesuai aturan tata ruang melalui OSS', 'Beban Jasa Konsultansi: Paket 4 (Non Kontruksi); A. Persiapan Dokumen RDTR Digital 1. Penyusunan dokumen RDTR sesuai Permen ATR/BPN termasuk peraturan perundangan dan lampiran peta. 2. Pembuatan peta digital berformat gdb (geodatabase) dan peta georeferensi 3. Penyusunan Tabel ITBX (Indikasi Terbatas, Bersyarat, dan X) 4. Penyusunan Database Peraturan Zonasi (DBPZ) B. Proses Unggah dan Sinkronisasi Sistem 1. Unggah dokumen-dokumen standar ke sub-sistem GISTARU (RTR Builder). 2. Unggah peta RDTR ke server peta nasional dan DBPZ ke aplikasi RDTR interaktif. C. Verifikasi dan Uji Coba 1. Melakukan uji petik lapangan untuk memastikan kesesuaian data digital dengan kondisi eksisting. 2. Uji coba (simulasi) otomatisasi penerbitan Konfirmasi Kesesuaian Kegiatan Pemanfaatan Ruang (KKKPR) di sistem OSS RBA D. Penerbitan dan Pelaporan 1. Tersedianya dokumen RDTR yang lengkap, standar, dan siap integrasi resmi. 2. Laporan hasil uji coba dan data yang telah siap diintegrasikan ke OSS.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 914687);
