INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63394674', 63394674, 'analyze_legacy', 'Kab. Nganjuk', 'kabkota', 'Rumah Sakit Daerah Nganjuk', 'Belanja Alat/bahan untuk Kegiatan Kantor-Benda Pos', 'Barang', 'Dikecualikan', 'Jawa Timur, Nganjuk (Kab.)', 31500000, 'January 2026', 'BLUD', 1, 1, '1 Paket', 'Penyediaan alat dan bahan penunjang kegiatan administrasi perkantoran berupa benda pos yang digunakan untuk mendukung kelancaran surat-menyurat dan pengelolaan dokumen resmi, meliputi pengiriman berkas/dokumen, penggunaan perangko sesuai tarif layanan pos, serta penyediaan meterai untuk pengesahan dokumen sesuai ketentuan peraturan perundang-undangan. 1. Biaya Pengiriman Berkas/Dokumen Pengadaan jasa pengiriman berkas dan/atau dokumen kedinasan melalui layanan pos atau jasa pengiriman resmi guna mendukung kelancaran korespondensi dan distribusi dokumen administrasi, baik internal maupun eksternal instansi. 2. Perangko Rp. 3000,- Pengadaan perangko dengan nominal Rp3.000,- yang digunakan untuk pengiriman surat/dokumen dinas melalui layanan pos sesuai dengan ketentuan tarif yang berlaku. 3. Perangko Rp. 6000,- Pengadaan perangko dengan nominal Rp6.000,- yang digunakan untuk pengiriman surat/dokumen dinas melalui layanan pos sesuai dengan kebutuhan pengiriman dan ketentuan tarif layanan pos. 4. Meterai Rp. 10.000,- Pengadaan meterai nominal Rp10.000,- yang digunakan untuk pengesahan dokumen resmi instansi sesuai dengan ketentuan peraturan perundang-undangan yang berlaku.', '1. Biaya Pengiriman Berkas/Dokumen Jenis layanan: Jasa pengiriman dokumen/berkas Media pengiriman: Layanan pos atau jasa pengiriman resmi dan legal Kondisi dokumen: Utuh, rapi, dan sesuai alamat tujuan Waktu pengiriman: Sesuai standar layanan pengiriman yang dipilih Bukti pengiriman: Resi atau tanda bukti pengiriman yang sah 2. Perangko Nominal Rp3.000,- Jenis: Perangko resmi yang diterbitkan oleh PT Pos Indonesia Nominal: Rp3.000,- per keping Kondisi: Baru, belum digunakan, dan tidak rusak Fungsi: Untuk pengiriman surat/dokumen dinas sesuai tarif yang berlaku Keabsahan: Berlaku dan diakui secara resmi oleh penyelenggara layanan pos 3. Perangko Nominal Rp6.000,- Jenis: Perangko resmi yang diterbitkan oleh PT Pos Indonesia Nominal: Rp6.000,- per keping Kondisi: Baru, belum digunakan, dan tidak rusak Fungsi: Untuk pengiriman surat/dokumen dinas sesuai tarif layanan pos Keabsahan: Berlaku dan diakui secara resmi 4. Meterai Nominal Rp10.000,- Jenis: Meterai tempel atau meterai elektronik sesuai ketentuan Nominal: Rp10.000,- Kondisi: Baru, belum digunakan Fungsi: Pengesahan dokumen resmi instansi Dasar hukum: Sesuai peraturan perundang-undangan tentang Bea Meterai', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 914768);
