INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63374484', 63374484, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA MUSEUM KESEJARAHAN JAKARTA', 'Pemanfaatan Teknologi Informasi Museum Kesejarahan Jakarta', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Barat (Kota)', 10999018912, 'June 2026', 'APBD', 1, 1, '78 Unit dan 4 Buah', 'Pekerjaan ini meliputi pengadaan, instalasi, konfigurasi, dan pengujian perangkat teknologi informasi dan multimedia guna mendukung penyajian informasi, pameran digital, dokumentasi, pengelolaan data, serta peningkatan layanan edukasi dan interaksi pengunjung di Museum Kesejarahan Jakarta. Seluruh perangkat yang disediakan harus baru, berfungsi optimal, kompatibel satu sama lain, serta didukung layanan purna jual dan garansi resmi.', 'Spesifikasi pekerjaan meliputi pengadaan perangkat teknologi informasi dan multimedia berupa projector dengan tingkat kecerahan minimal 7.000 lumens dan teknologi DLP; sistem tata suara line array speaker berdaya tinggi untuk kebutuhan audio pameran; perangkat penyimpanan data terpusat Network Attached Storage (NAS) berkapasitas besar dengan dukungan RAID dan jaringan berkecepatan tinggi; lisensi ArcGIS Production Mapping untuk pengelolaan data spasial museum; Interactive Flat Panel Display (IFPD) berukuran 86 inci lengkap dengan OPS, webcam, dan trolley; perangkat Virtual Reality berkapasitas 256 GB untuk penyajian konten sejarah berbasis imersif; perangkat jaringan Mikrotik untuk mendukung konektivitas dan manajemen jaringan; kamera video profesional setara 6K full-frame untuk dokumentasi dan produksi konten; serta monitor LED Full HD 42 inci sebagai media tampilan informasi digital, yang seluruhnya harus baru, berfungsi optimal, kompatibel, dan didukung garansi resmi sesuai ketentuan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 915067);
