INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63394254', 63394254, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA PELABUHAN PERIKANAN', 'Peninggian Area Bongkar Muat UPI', 'Pekerjaan Konstruksi', 'E-Purchasing', 'DKI Jakarta, Jakarta Utara (Kota)', 6032054784, 'May 2026', 'APBD', 1, 1, '1 paket', 'Pekerjaan peninggian area bongkar muat Unit Pengolahan Ikan (UPI) di lingkungan Unit Pengelola Pelabuhan Perikanan (UPPP) berupa peninggian jalan dan area kerja, yang dilaksanakan untuk meningkatkan elevasi permukaan guna mengurangi genangan/banjir serta mendukung kelancaran aktivitas bongkar muat. Kegiatan pekerjaan meliputi persiapan dan pengamanan lokasi, pengaturan lalu lintas internal agar operasional UPI tetap berjalan, serta pembersihan area kerja. Selanjutnya dilakukan pekerjaan pengupasan lapisan eksisting, perbaikan dan pemadatan tanah dasar, serta penambahan material urugan sesuai elevasi rencana. Pekerjaan dilanjutkan dengan pembangunan lapis pondasi bawah dan lapis pondasi atas, diikuti pekerjaan perkerasan jalan sesuai desain teknis (beton/aspal atau perkerasan lain sesuai perencanaan). Selain itu, dilakukan penyesuaian dan pembangunan sistem drainase, kemiringan permukaan, serta sambungan dengan area eksisting agar aliran air berjalan baik dan tidak menimbulkan genangan. Seluruh pekerjaan dilaksanakan sesuai gambar rencana, spesifikasi teknis, dan standar keselamatan kerja (K3), disertai pengendalian mutu dan pengujian hasil pekerjaan. Hasil akhir pekerjaan berupa area bongkar muat UPI yang lebih tinggi, kuat, aman, dan siap digunakan untuk mendukung kegiatan operasional selama masa layanan.', 'Pekerjaan Peninggian Area Bongkar Muat Unit Pengolahan Ikan (UPI) di lingkungan Unit Pengelola Pelabuhan Perikanan (UPPP) berupa peninggian jalan dan area kerja, dilaksanakan berdasarkan dokumen perencanaan teknis yang telah disetujui, dengan memperhatikan standar pekerjaan jalan dan bangunan pelabuhan serta ketentuan keselamatan kerja. Ruang lingkup spesifikasi meliputi: Pekerjaan Persiapan Pembersihan dan pengamanan area kerja Pengaturan akses dan lalu lintas internal selama pekerjaan Pemasangan rambu dan perlengkapan keselamatan kerja (K3) Pekerjaan Tanah dan Urugan Pembongkaran lapisan eksisting yang terdampak Perbaikan dan pemadatan tanah dasar Pekerjaan urugan untuk peninggian sesuai elevasi rencana Pemadatan lapis demi lapis hingga mencapai kepadatan yang dipersyaratkan Pekerjaan Lapis Pondasi Pekerjaan lapis pondasi bawah dan atas sesuai spesifikasi teknis Pengujian ketebalan dan kepadatan lapisan pondasi Pekerjaan Perkerasan Jalan Pekerjaan perkerasan (beton/aspal/perkerasan lain sesuai perencanaan) Pengaturan kemiringan permukaan untuk aliran air Penyambungan dengan jalan dan area eksisting Pekerjaan Drainase Pembangunan dan/atau penyesuaian saluran drainase Pemasangan inlet, outlet, dan pengendalian limpasan air Pengujian fungsi drainase pasca pekerjaan Pengendalian Mutu dan Keselamatan Pengujian mutu material dan hasil pekerjaan Penerapan standar Keselamatan dan Kesehatan Kerja (K3) Pembersihan area setelah pekerjaan selesai Hasil Pekerjaan Area bongkar muat UPI dengan elevasi lebih tinggi, struktur kuat, permukaan rata, dan drainase berfungsi baik Siap digunakan untuk mendukung kegiatan bongkar muat secara aman dan berkelanjutan Hasil pekerjaan harus memenuhi spesifikasi teknis, mutu, waktu, dan keselamatan sebagaimana ditetapkan dalam dokumen kontrak dan peraturan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 915518);
