INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63351960', 63351960, 'analyze_legacy', 'Kab. Karanganyar', 'kabkota', 'Dinas Pekerjaan Umum dan Perumahan Rakyat', 'Beban Jasa Konsultansi Berorientasi Layanan-Jasa Khusus', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Tengah, Karanganyar (Kab.)', 100000000, 'February 2026', 'APBD', 1, 1, '1 Paket', 'Beban Jasa Konsultansi Berorientasi Layanan-Jasa Khusus; Uraian pekerjaan pendampingan Lintas Sektor (Linsek) dan Persetujuan Substansi (Persub) Rencana Detail Tata Ruang (RDTR) Colomadu adalah serangkaian kegiatan jasa konsultansi untuk membantu Pemerintah Kabupaten Karanganyar dalam proses asistensi, pembahasan, hingga terbitnya Persub dari Kementerian ATR/BPN untuk wilayah Colomadu', 'Beban Jasa Konsultansi: Paket 4 (Non Kontruksi); A. Tahap Persiapan dan Pra-Lintas Sektor (Pra-Linsek) : 1. Pemeriksaan Dokumen: Meninjau kelengkapan materi teknis RDTR, peta (skala 1:5.000), Raperkada RDTR, KLHS, dan dokumen pendukung lainnya. 2. Klinik Persiapan Linsek: Menyelenggarakan diskusi teknis atau "klinik" bersama Kementerian ATR/BPN untuk membahas potensi isu/catatan sebelum rapat resmi. 3. Penyusunan Materi Paparan: Menyiapkan paparan (presentasi) yang akan disampaikan Bupati/Walikota atau perwakilan Pemda dalam rapat Lintas Sektor. B. Tahap Rapat Lintas Sektor (Rakor Linsek) : 1. Fasilitasi Rapat: Mendampingi Pemda dalam Rapat Koordinasi Lintas Sektor yang dihadiri kementerian/lembaga terkait dan OPD teknis. 2. Penyusunan Bahan Tanggapan: Membantu menyusun tanggapan atas masukan dan catatan dari perwakilan K/L (Kementerian/Lembaga) terkait materi teknis RDTR. 3. Notulensi dan Berita Acara: Mendokumentasikan hasil kesepakatan rakor linsek. C. Tahap Perbaikan dan Penerbitan Persub (Pasca-Linsek) : 1. Revisi Materi Teknis: Melakukan perbaikan pada dokumen materi teknis, album peta, dan Raperkada RDTR berdasarkan hasil Rapat Lintas Sektor. 2. Asistensi Teknis: Mendampingi Pemda dalam asistensi perbaikan materi dengan Direktorat Bina Perencanaan Tata Ruang Daerah. 3. Finalisasi Dokumen: Memastikan dokumen akhir telah sesuai dengan catatan linsek dan siap untuk ditandatangani. 4. Pendampingan Penerbitan Persub: Mengawal proses hingga keluarnya Persetujuan Substansi (Persub) dari Menteri ATR/BPN.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 915561);
