INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63351962', 63351962, 'analyze_legacy', 'Kab. Karanganyar', 'kabkota', 'Dinas Pekerjaan Umum dan Perumahan Rakyat', 'Beban Jasa Konsultansi Berorientasi Layanan-Jasa Khusus', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Tengah, Karanganyar (Kab.)', 100000000, 'February 2026', 'APBD', 1, 1, '1 Paket', 'Beban Jasa Konsultansi Berorientasi Layanan-Jasa Khusus; Uraian pekerjaan integrasi OSS untuk RDTR adalah proses teknis dan substantif untuk menyelaraskan Rencana Detail Tata Ruang (RDTR) digital dengan sistem perizinan nasional OSS di wilayah Colomadu yang meliputi penyusunan dokumen standar (peta georeferensi, tabel zonasi, DBPZ), unggah ke sistem GISTARU (RTR Builder), uji petik data, hingga memastikan kesiapan sistem untuk menerbitkan KKPR secara elektronik, guna mempercepat investasi dengan memastikan kesesuaian ruang berbasis data digital dan terintegrasi.', 'Beban Jasa Konsultansi: Paket 4 (Non Kontruksi); A. Standar Dokumen dan Data ; 1. Perkada/Peraturan Daerah 2. Peta Digital (Digitalisasi) 3. Tabel ITBX (Indikasi Terkait Bidang X) 4. DBPZ (Database Peraturan Zonasi) 5. Peta Dasar B. Spesifikasi Teknis Integrasi 1. Platform: Menggunakan modul RTR Builder (GISTARU) untuk unggah data, lalu integrasi ke OSS RBA. 2. Format Spasial: Data peta (polygon) harus diunggah dan diakses melalui layanan WMS/WFS (OGC Standard), memastikan interoperabilitas. 3. Prosedur Unggah: Unggah peta ke server peta, unggah DBPZ ke aplikasi RDTR Interaktif, dan lakukan uji coba integrasi (scenario test). 4. Validasi Otomatis: Sistem akan melakukan validasi otomatis terhadap data yang diunggah untuk menerbitkan KKKPR. 5. Logika Zonasi: Penyesuaian atribut data spasial dan logika zonasi agar sesuai dengan aturan di OSS RBA (Diizinkan, Terbatas, Bersyarat, Ditolak).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 915687);
