INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63353464', 63353464, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN LANJUTAN', 'Konsumsi (makan dan snack)', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 10125000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 125, OK, @ 81000 )', '1. Konsumsi (makan dan snack) ( 125, OK, @ 81000 ); Uraian pekerjaan meliputi penyediaan konsumsi berupa makanan dan snack untuk mendukung pelaksanaan kegiatan rapat, koordinasi, dan pertemuan kedinasan. Pekerjaan mencakup pengadaan, pengemasan, dan penyediaan konsumsi sesuai jumlah peserta dan waktu pelaksanaan kegiatan, dengan memperhatikan standar kebersihan, keamanan pangan, dan kelayakan konsumsi, serta ketentuan peraturan perundang-undangan yang berlaku.', 'Spesifikasi pekerjaan meliputi penyediaan konsumsi berupa makanan dan snack untuk mendukung pelaksanaan kegiatan. Konsumsi yang disediakan harus dalam kondisi layak, higienis, dan aman dikonsumsi, menggunakan bahan yang baik dan tidak kedaluwarsa, serta disesuaikan dengan jumlah peserta dan waktu pelaksanaan kegiatan. Penyedia bertanggung jawab atas pengadaan, pengemasan, dan penyediaan konsumsi sesuai ketentuan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 915839);
