INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63353024', 63353024, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA MUSEUM KESEJARAHAN JAKARTA', 'Pemeliharaan Gedung dan Bangunan Penunjang Museum', 'Jasa Konsultansi', 'E-Purchasing', 'DKI Jakarta, Jakarta Barat (Kota) | DKI Jakarta, Jakarta Pusat (Kota) | DKI Jakarta, Jakarta Pusat (Kota) | DKI Jakarta, Jakarta Pusat (Kota)', 4994079420, 'March 2026', 'APBD', 1, 1, '576 M2', 'Pekerjaan pemeliharaan gedung dan bangunan penunjang pada Unit Pengelola Museum Kesejarahan Jakarta yang meliputi Museum Sejarah Jakarta, Museum Taman Prasasti, Museum Joang ’45, dan Museum MH. Thamrin, berupa pekerjaan persiapan, penerapan SMKK konstruksi, perbaikan dan penggantian atap, perbaikan bangunan, pekerjaan saluran dan drainase, pekerjaan lantai dan taman, pekerjaan plafon dan partisi, pekerjaan pengecatan interior dan eksterior, perbaikan pintu dan fasilitas bangunan, pemasangan serta perbaikan instalasi CCTV, pekerjaan waterproofing, serta pekerjaan penunjang lainnya sesuai kebutuhan pemeliharaan bangunan museum.', 'Pekerjaan dilaksanakan sesuai standar teknis konstruksi bangunan gedung dengan menggunakan material yang memenuhi spesifikasi seperti rangka atap kayu jati kelas II, genteng pengganti sesuai tipe eksisting, atap zincalume berwarna, plafon gypsum/GRC, partisi GRC, cat interior dan eksterior setara Propan/Propan Heritage, saluran u-ditch beton, batu andesit, buis beton, sistem waterproofing, instalasi CCTV berbasis jaringan UTP Cat 6 dengan perangkat NVR dan monitor, serta pekerjaan lainnya yang mengacu pada standar mutu pekerjaan konstruksi, keselamatan kerja (SMKK), dan ketentuan teknis yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 2, 918391);
