INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63351956', 63351956, 'analyze_legacy', 'Kab. Karanganyar', 'kabkota', 'Dinas Pekerjaan Umum dan Perumahan Rakyat', 'Beban Jasa Konsultansi Berorientasi Layanan-Jasa Khusus', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Tengah, Karanganyar (Kab.)', 50000000, 'February 2026', 'APBD', 1, 1, '1 Paket', 'Beban Jasa Konsultansi Berorientasi Layanan-Jasa Khusus; Pengklarifikasian Coding Database KBLI OSS dan Advice Planning untuk Rencana Detail Tata Ruang (RDTR) Colomadu merupakan layanan konsultasi teknis atau administratif untuk memastikan kesesuaian antara jenis usaha yang dijalankan dengan aturan zonasi tata ruang yang berlaku di Colomadu dengan di sistem Online Single Submission (OSS).', 'Beban Jasa Konsultansi: Paket 2 (Non Kontruksi); A. Pengklarifikasian Coding Database KBLI OSS : Identifikasi Kegiatan Usaha: 1. Menganalisis dokumen perusahaan (Akta, NIB, tujuan perusahaan) untuk menentukan KBLI yang paling sesuai. 2. Verifikasi Kode KBLI: Memastikan kode 5-digit KBLI yang dipilih relevan dengan kegiatan operasional riil untuk menghindari penolakan izin. 3. Klarifikasi/Penyesuaian: Mengurus perubahan atau penambahan KBLI jika kode yang lama tidak sesuai dengan update sistem atau peraturan terbaru. 4. Analisis Risiko: Menentukan tingkat risiko usaha (Rendah, Menengah Rendah, Menengah Tinggi, Tinggi) berdasarkan KBLI untuk menentukan persyaratan izin. B. Advice Planning Untuk RDTR : 1. Pengecekan Kesesuaian Tata Ruang: Menganalisis lokasi proyek/tanah terhadap Peta RDTR untuk menentukan zonasi (misal: zona industri, komersial, perumahan). 2. Interpretasi RDTR & Zonasi: Menjabarkan aturan zonasi yang rinci, termasuk intensitas bangunan (Koefisien Dasar Bangunan/KDB, Koefisien Lantai Bangunan/KLB). 3. Penerbitan/Pengurusan Advice Planning (KRK): Mengurus Keterangan Rencana Kota (KRK) atau Advice Planning sebagai dasar teknis perizinan bangunan. 4. Tautan KBLI-RDTR (KKPR): Memastikan KBLI yang dipilih di OSS (poin 1) sesuai dengan peruntukan lahan dalam RDTR untuk meloloskan status Kesesuaian Kegiatan Pemanfaatan Ruang (KKPR).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 918701);
